--
-- Table structure for table `md_supplier`
--

DROP TABLE IF EXISTS `md_supplier`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `md_supplier` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint NOT NULL COMMENT '租户ID【多租户隔离字段】',
  `supplier_code` varchar(64) NOT NULL COMMENT '供应商编码',
  `supplier_name` varchar(200) NOT NULL COMMENT '供应商名称',
  `short_name` varchar(100) DEFAULT NULL COMMENT '简称',
  `supplier_type` varchar(50) DEFAULT NULL COMMENT '供应商类型(取字典 supplier_type)',
  `credit_code` varchar(64) DEFAULT NULL COMMENT '统一社会信用代码',
  `tax_no` varchar(64) DEFAULT NULL COMMENT '纳税人识别号',
  `tax_type` varchar(20) DEFAULT 'GENERAL' COMMENT '纳税人类型:GENERAL/SMALL',
  `pay_terms` varchar(50) DEFAULT NULL COMMENT '付款条件',
  `currency_code` varchar(10) DEFAULT NULL COMMENT '结算币种',
  `invoice_type` varchar(20) DEFAULT NULL COMMENT '发票类型(专票/普票)',
  `address` varchar(500) DEFAULT NULL COMMENT '地址',
  `tel` varchar(30) DEFAULT NULL COMMENT '电话',
  `contact_name` varchar(50) DEFAULT NULL COMMENT '联系人',
  `contact_phone` varchar(30) DEFAULT NULL COMMENT '联系人电话',
  `blacklist` tinyint NOT NULL DEFAULT '0' COMMENT '是否黑名单:0否 1是(黑名单禁止发起付款)',
  `status` varchar(20) NOT NULL DEFAULT 'NORMAL' COMMENT '状态:NORMAL/DISABLED',
  `remark` varchar(500) DEFAULT NULL,
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_supplier_code` (`tenant_id`,`supplier_code`),
  KEY `idx_tenant` (`tenant_id`),
  KEY `idx_tenant_name` (`tenant_id`,`supplier_name`)
) ENGINE=InnoDB AUTO_INCREMENT=130763 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='只读快照(MDG-102③)：由 core MDM FsscSupplierSnapshotService 定时反向同步，唯一权威源=unierp_core.md_supplier，禁止业务直写；遗留非标码行待 MDG-207 处置';
/*!40101 SET character_set_client = @saved_cs_client */;

